for (node in ctx.payload.nodes.values()) {
  for (fs in node.fs.data) {
    double available = fs.available_in_bytes;
    double total = fs.total_in_bytes;
    double used_percentage = ((total - available) / total) * 100;
    if (used_percentage > 85) {
      return true;
    }
  }
}
return false;

for (node in ctx.payload.nodes.values()) {
  double heap_used = node.jvm.mem.heap_used_percent;
  if (heap_used > 90) {
    return true;
  }
}
return false;

int recent_indices = 0;
long one_hour_ago = ctx.execution_time.millis - 3600000;
for (index in ctx.payload) {
  if (index.index.startsWith("logs-")) {
    try {
      long creation_time = Long.parseLong(index['creation.date.string']);
      if (creation_time > one_hour_ago) {
        recent_indices++;
      }
    } catch (Exception e) {
      // Skip if timestamp parsing fails
    }
  }
}
return recent_indices > 10; // Alert if more than 10 indices created in last hour
